    /** 여름(N2)·겨울(N4) 세트는 1차 ⬜ — 그릴 때까지 형태만 봄·가을 것을 빌린다. 색은 달 팔레트가 정한다 */
    fun meadow(season: Season): Meadow = when (season) {
        Season.SPRING, Season.SUMMER -> meadowSpring
        Season.AUTUMN, Season.WINTER -> meadowAutumn
    }

